package local.proskurnin.preview;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.Color;import android.widget.*;
public class DreamCacheActivity extends Activity {
 DreamCache cache;TextView info;boolean visible;final Handler h=new Handler();
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 Button button(LinearLayout root,String text,Runnable action){Button b=new Button(this);b.setText(text);b.setTextSize(18);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setMinHeight(0);b.setMinimumHeight(0);b.setPadding(dp(16),0,dp(16),0);android.graphics.drawable.StateListDrawable bg=new android.graphics.drawable.StateListDrawable();for(boolean focused:new boolean[]{true,false}){android.graphics.drawable.GradientDrawable g=new android.graphics.drawable.GradientDrawable();g.setColor(focused?0xff344863:0xff192332);g.setCornerRadius(dp(10));if(focused)g.setStroke(dp(1),0xffc5dcff);bg.addState(focused?new int[]{android.R.attr.state_focused}:new int[]{},g);}b.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(42));lp.topMargin=dp(6);root.addView(b,lp);b.setOnClickListener(v->action.run());return b;}
 public void onCreate(Bundle state){super.onCreate(state);cache=new DreamCache(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(64,40,64,30);root.setBackgroundColor(0xff0b1220);ScrollView container=new ScrollView(this);container.setFillViewport(true);container.addView(root);setContentView(container);TextView title=new TextView(this);title.setText("Офлайн-заставка · 5 роликов");title.setTextColor(Color.WHITE);title.setTextSize(28);root.addView(title);info=new TextView(this);info.setTextSize(19);info.setTextColor(0xffb9c6d8);info.setPadding(0,16,0,16);root.addView(info);info.setText(cache.summary()+"\nЛимит 300 МБ включает временную загрузку. Новое видео заменяет старое только после проверки.\nОбновление по одному, не чаще 5 мин, только пока открыта заставка. Видео 1080p / 30 кадров в секунду, без звука.");
  button(root,"Загрузить / обновить ролики",()->{if(DreamCache.working.get())return;cache=new DreamCache(this);cache.sync(cache.ready().length<5,text->h.post(()->{if(visible)info.setText(text);}));});
  Button updates=button(root,"",()->{});updates.setText(getSharedPreferences("preview",0).getBoolean("dream_cache_update",true)?"Обновлять ролики: вкл":"Обновлять ролики: выкл");updates.setOnClickListener(v->{boolean value=!getSharedPreferences("preview",0).getBoolean("dream_cache_update",true);getSharedPreferences("preview",0).edit().putBoolean("dream_cache_update",value).apply();updates.setText(value?"Обновлять ролики: вкл":"Обновлять ролики: выкл");if(!value)cache.stop();});
  Button enabled=button(root,"",()->{});enabled.setText(getSharedPreferences("preview",0).getBoolean("dream_cache_enabled",true)?"Локальная заставка: вкл":"Локальная заставка: выкл");enabled.setOnClickListener(v->{boolean value=!getSharedPreferences("preview",0).getBoolean("dream_cache_enabled",true);getSharedPreferences("preview",0).edit().putBoolean("dream_cache_enabled",value).apply();enabled.setText(value?"Локальная заставка: вкл":"Локальная заставка: выкл");if(!value)cache.stop();});
  button(root,"Выбрать системную заставку",()->startActivity(new Intent().setComponent(new ComponentName("com.android.tv.settings","com.android.tv.settings.device.display.daydream.DaydreamActivity"))));
  button(root,"Удалить загруженные ролики",()->new AlertDialog.Builder(this).setMessage("Удалить только локальные видео заставки?").setPositiveButton("Удалить",(d,n)->{cache.stop();clearWhenIdle();}).setNegativeButton("Отмена",null).show());
  button(root,"Назад",()->finish());
 }
 void clearWhenIdle(){if(!visible)return;if(DreamCache.working.get()){info.setText("Останавливаю загрузку…");h.postDelayed(()->clearWhenIdle(),200);return;}cache.clear();info.setText(cache.summary());}
 protected void onResume(){super.onResume();visible=true;}
 protected void onPause(){visible=false;cache.stop();super.onPause();}
 protected void onDestroy(){cache.stop();h.removeCallbacksAndMessages(null);super.onDestroy();}
}
